  taskForm.append(taskLabel, taskControls, taskError);

  const filterLabel = document.createElement('label');
  filterLabel.htmlFor = 'task-filter';
  filterLabel.textContent = 'Task filter';
  const filter = document.createElement('select');
  filter.id = 'task-filter';
  for (const value of ['All', 'Open', 'Completed']) {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = value;
    filter.append(option);
  }
  const taskList = document.createElement('section');
  taskList.setAttribute('aria-label', 'Tasks');
  detail.append(taskForm, filterLabel, filter, taskList);

  async function renderTasks() {
    const response = await fetch(`/api/projects/${project.id}/tasks`);
    if (!response.ok) throw new Error('Unable to load tasks');
    const tasks = await response.json();
    taskList.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed || filter.value === 'Completed' && !task.completed) continue;
      const row = document.createElement('div');
      row.dataset.testid = 'task-row';
      row.className = 'task-row';
      const title = document.createElement('span');
      title.textContent = task.title;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = Boolean(task.completed);
      checkbox.disabled = Boolean(project.archived);
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        const result = await fetch(`/api/projects/${project.id}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked })
        });
        if (!result.ok) { checkbox.checked = !checkbox.checked; return; }
        await renderTasks();
      });
      row.append(title, checkbox);
      taskList.append(row);
    }
  }
  filter.addEventListener('change', () => renderTasks().catch(() => {}));
  taskForm.addEventListener('submit', async event => {
    event.preventDefault();
    taskError.hidden = true;
    const title = taskInput.value.trim();
    if (!title) { taskError.textContent = 'Task title is required'; taskError.hidden = false; return; }
    const response = await fetch(`/api/projects/${project.id}/tasks`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title })
    });
    if (!response.ok) {
      const result = await response.json();
      taskError.textContent = result.error || 'Unable to create task';
      taskError.hidden = false;
      return;
    }
    taskInput.value = '';
    await renderTasks();
  });
  await renderTasks();
}

projectFilter.addEventListener('change', () => renderList().catch(() => {}));

form.addEventListener('submit', async event => {
  event.preventDefault();
  error.hidden = true;
  const name = input.value.trim();
  if (!name) {
    error.textContent = 'Project name is required';
    error.hidden = false;
    return;
  }
  const response = await fetch('/api/projects', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
  });
  if (!response.ok) {
    const result = await response.json();
    error.textContent = result.error || 'Unable to create project';
    error.hidden = false;
    return;
  }
  input.value = '';
  await renderList();
});

renderRoute().catch(error => {
  const message = document.createElement('p');
  message.setAttribute('role', 'alert');
  message.textContent = error.message;
  app.append(message);
});

* { box-sizing: border-box; }
body { margin: 0; background: #f5f7fa; color: #172033; font: 16px/1.5 system-ui, sans-serif; }
.container { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #e2e7ef; border-radius: 12px; box-shadow: 0 8px 24px #15223a0d; }
h1 { margin: 0 0 28px; font-size: 2rem; }
label { display: block; margin-bottom: 8px; font-weight: 600; }
.form-row { display: flex; gap: 12px; }
input { flex: 1; min-width: 0; padding: 10px 12px; border: 1px solid #aeb8c8; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 6px; background: #2459c4; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #19469f; }
.project-row, .task-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-top: 14px; padding: 14px 16px; border: 1px solid #e2e7ef; border-radius: 8px; }
.task-form { margin-top: 28px; }
#task-filter { display: block; min-width: 160px; padding: 9px 12px; border: 1px solid #aeb8c8; border-radius: 6px; font: inherit; }
.task-row input[type="checkbox"] { flex: none; width: 20px; height: 20px; }
#error { color: #b42318; margin-bottom: 0; }
@media (max-width: 600px) { .container { margin: 20px 12px; padding: 22px; } .form-row { align-items: stretch; flex-direction: column; } }

