* { box-sizing: border-box; }
body { margin: 0; background: #f5f7fa; color: #172033; font: 16px/1.5 system-ui, sans-serif; }
.container { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #e2e7ef; border-radius: 12px; box-shadow: 0 8px 24px #15223a0d; }
h1 { margin: 0 0 28px; font-size: 2rem; }
label { display: block; margin-bottom: 8px; font-weight: 600; }
.form-row { display: flex; gap: 12px; }
input { flex: 1; min-width: 0; padding: 10px 12px; border: 1px solid #aeb8c8; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 6px; background: #2459c4; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #19469f; }
.project-row, .task-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-top: 14px; padding: 14px 16px; border: 1px solid #e2e7ef; border-radius: 8px; }
.task-form { margin-top: 28px; }
#task-filter { display: block; min-width: 160px; padding: 9px 12px; border: 1px solid #aeb8c8; border-radius: 6px; font: inherit; }
.task-row input[type="checkbox"] { flex: none; width: 20px; height: 20px; }
#error { color: #b42318; margin-bottom: 0; }
@media (max-width: 600px) { .container { margin: 20px 12px; padding: 22px; } .form-row { align-items: stretch; flex-direction: column; } }

